<?php
declare(strict_types=1);
require __DIR__.'/shipping.php';
use Shipping\{Fulfilment,Ledger,Rules};
$settings=clone $s;$settings->providers['carrier']='helics';$settings->federationId='whole-carrier';$settings->peers['carrier']=['source'=>'logistics','endpoint'=>'logistics/events'];$shipping=new Fulfilment($db,$settings);$ledger=new Ledger($db,$settings);
$create=shippingSubmit(['action'=>'create','customer'=>'WHOLE-CARRIER','destination'=>'CUSTOMER-A','lines'=>[['sku'=>'PRODUCT','quantity'=>3]]]);shippingDrain();shippingSubmit(['action'=>'fulfil','reference'=>$create['id']]);shippingDrain();shippingSubmit(['action'=>'pack','reference'=>$create['id']]);shippingDrain();shippingSubmit(['action'=>'dispatch','reference'=>$create['id']]);shippingDrain();
$o=$shipping->order($create['id']);$line=$o['lines'][0];$intent=array_values(array_filter($o['intents'],fn($i)=>$i['kind']==='dispatch'))[0];$r=$ledger->status()['run'];
$request=$db->transaction(fn($u)=>$u->one("SELECT envelope FROM boundary_outbox WHERE run_id=? AND envelope->>'type'='logistics.request.v1'",[$r['id']]))['envelope'];
shippingCheck(($request['payload']['unit_ids']??[])===$line['unit_ids']&&array_sum(array_column($request['payload']['unit_manifest']??[],'quantity'))===3,'carrier request declares the exact owned whole units without splitting');
shippingCheck(($request['payload']['customer_destination']??null)==='CUSTOMER-A','carrier request preserves the customer address separately from the logical route');
function carrierAdvance(array $envelope):void {global $shipping,$db,$ledger;$shipping->ingest($envelope,'logistics/events');$db->transaction(fn($u)=>$u->execute('UPDATE boundary_outbox SET sent_at=clock_timestamp() WHERE run_id=?',[$envelope['run_id']]));shippingDrain();}
function carrierEnvelope(string $type,string $aggregate,int $version,array $payload):array {global $ledger,$settings,$o;$r=$ledger->status()['run'];return ['schema_version'=>'1.0','type'=>$type,'event_id'=>Rules::uuid4(),'federation_id'=>$settings->federationId,'run_id'=>$r['id'],'epoch'=>$r['epoch'],'correlation_id'=>$o['correlation_id'],'causation_id'=>$aggregate,'aggregate_id'=>$aggregate,'aggregate_version'=>$version,'source'=>'logistics','destination'=>'shipping','boundary'=>'carrier','effective_time'=>$r['granted']+1,'wall_time'=>(new DateTimeImmutable())->format(DateTimeInterface::ATOM),'quantity_unit'=>'item','payload'=>$payload];}
$transfer=Rules::uuid4();$assignment=['id'=>$transfer,'run_id'=>$r['id'],'epoch'=>$r['epoch'],'correlation_id'=>$o['correlation_id'],'external_reference'=>$intent['id'],'route'=>'DISPATCH-CUSTOMER','origin'=>'DISPATCH','destination'=>'CUSTOMER','customer_destination'=>'CUSTOMER-A','journey_seconds'=>20,'sku'=>$line['sku'],'quantity'=>3,'vehicle'=>'VAN-1','status'=>'assigned','custody'=>'origin','provider'=>true,'version'=>2,'planned_eta'=>null,'departed_at'=>null,'arrived_at'=>null,'unloaded_at'=>null,'received_at'=>null,'unit_ids'=>$line['unit_ids'],'unit_destinations'=>[$line['unit_ids'][0]=>'logistics.outbound.staging01']];
carrierAdvance(carrierEnvelope('logistics.assign.completed.v1',$transfer,2,$assignment));
$offers=$db->transaction(fn($u)=>$u->query("SELECT envelope FROM boundary_outbox WHERE run_id=? AND envelope->>'type'='handling.offered.v1'",[$r['id']]));
shippingCheck(count($offers)===count($line['unit_ids']),'assigned carrier automatically creates custody offers through the worker');
$h=$offers[0]['envelope']['payload'];$units=$shipping->snapshot()['handling']['units'];shippingCheck($units[0]['state']==='reserved'&&$units[0]['position']!==null&&$h['unit']['id']===$line['unit_ids'][0],'automatic offer retains source placement until receiver acceptance');
carrierAdvance(carrierEnvelope('handling.accepted.v1',$h['id'],$h['unit']['version'],[...$h,'state'=>'accepted']));
$units=$shipping->snapshot()['handling']['units'];shippingCheck($units[0]['state']==='in_transit'&&$units[0]['position']===null,'carrier acceptance atomically clears Shipping placement before departure publication');
$departure=$db->transaction(fn($u)=>$u->one("SELECT envelope FROM boundary_outbox WHERE run_id=? AND envelope->>'type'='handling.departed.v1'",[$r['id']]))['envelope'];shippingCheck($departure['payload']['departure_token']['unit_id']===$line['unit_ids'][0],'automatic departure preserves the requested barcode and durable proof');
$departedCarrier=[...$assignment,'status'=>'in_transit','custody'=>'vehicle','version'=>4,'departed_at'=>$ledger->status()['run']['granted'],'planned_eta'=>$ledger->status()['run']['granted']+20];
carrierAdvance(carrierEnvelope('logistics.depart.completed.v1',$transfer,4,$departedCarrier));shippingCheck($shipping->order($create['id'])['shipment']['journey_id']===$transfer,'shipment links the actual confirmed carrier journey');
echo "Shipping automatic carrier custody checks passed (controlled peer transport)\n";
// The source must reject a manifest the carrier wire cannot publish.
$r=$ledger->status()['run'];$db->transaction(fn($u)=>$u->execute('UPDATE boundary_outbox SET sent_at=clock_timestamp() WHERE run_id=?',[$r['id']]));
$manifest=[];for($n=0;$n<9;$n++)$manifest[]=['id'=>Rules::uuid4(),'quantity'=>1];shippingSubmit(['action'=>'intake','sku'=>'NINE','quantity'=>9,'units'=>$manifest]);shippingDrain();
$nine=shippingSubmit(['action'=>'create','customer'=>'NINE-UNITS','destination'=>'CUSTOMER-A','lines'=>[['sku'=>'NINE','quantity'=>9]]]);shippingDrain();shippingSubmit(['action'=>'fulfil','reference'=>$nine['id']]);shippingDrain();shippingSubmit(['action'=>'pack','reference'=>$nine['id']]);shippingDrain();$before=$db->transaction(fn($u)=>$u->query("SELECT id FROM boundary_outbox WHERE run_id=? AND envelope->>'type'='logistics.request.v1'",[$r['id']]));
$rejected=shippingSubmit(['action'=>'dispatch','reference'=>$nine['id']]);shippingDrain();$outcome=$db->transaction(fn($u)=>$u->one('SELECT outcome FROM shipping_commands WHERE id=?',[$rejected['id']]));
shippingCheck($outcome['outcome']==='rejected'&&$shipping->order($nine['id'])['status']==='packed'&&$shipping->order($nine['id'])['shipment']===null,'unsupported nine-unit dispatch rejects before shipment creation');
$after=$db->transaction(fn($u)=>$u->query("SELECT id FROM boundary_outbox WHERE run_id=? AND envelope->>'type'='logistics.request.v1'",[$r['id']]));shippingCheck($after===$before,'unsupported carrier manifest cannot strand an unpublishable outbox entry');
